#!/usr/bin/env python3
"""Проверка витрины для участников: канонические файлы есть, кухня сборки отсутствует."""
from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

REQUIRED = [
    "README.md",
    "LICENSE",
    "01_доклад/Не_просто_накормить_доклад_стиль_claude.pdf",
    "01_доклад/Не_просто_накормить_КРАТКАЯ_версия.pdf",
    "02_презентация/презентация_v6/Презентация_v6_Не_просто_накормить.pdf",
    "02_презентация/презентация_v6/Презентация_v6_Не_просто_накормить.pptx",
    "03_семинарский_пакет/Памятка_что_унести_в_регион.pdf",
    "03_семинарский_пакет/Вариативное_питание_опыт_реализации.pdf",
    "03_семинарский_пакет/21_если_инспектор_не_принял.pdf",
    "03_семинарский_пакет/Калькулятор_стоимости_вариативности.xlsx",
    "03_семинарский_пакет/05_чеклист_понедельник.md",
    "05_раздатка_canva/Раздатка_Лестница_вариативности_A4.pdf",
    "05_раздатка_canva/Раздатка_Моя_еда_мой_выбор_easy_read_A4.pdf",
    "05_раздатка_canva/Раздатка_План_Б_питание_при_закрытии_столовой_A4.pdf",
    "05_раздатка_canva/Раздатка_Таблица_замен_A4.pdf",
    "05_раздатка_canva/Раздатка_Что_сделать_в_понедельник_A4.pdf",
    "05_раздатка_canva/Раздатка_Шесть_измерений_стола_A4.pdf",
    "06_викторина_canva/Викторина_диплом_A4.pdf",
    "06_викторина_canva/Викторина_карточки_ответов_АБВГ.pdf",
    "06_викторина_canva/Викторина_плакат_QR.pdf",
    "06_викторина_canva/Викторина_тент_Стол_1.pdf",
]

FORBIDDEN = [
    "НАЧНИТЕ_ЗДЕСЬ.md",
    "ПРОЧТИ_МЕНЯ.md",
    "CHANGELOG.md",
    "requirements.txt",
    "семинар_пакет_2026.zip",
    "проект",
    "07_редакция_доклада_v2",
    "выступление_26.08",
    "пакет_26.08",
    ".cursor",
    "02_презентация/archive",
    "02_презентация/презентация_v5_21_слайд",
    "02_презентация/презентация_v4_38_слайдов",
    "02_презентация/презентация_kimi_34_слайда",
    "04_приложения_и_реестры",
]


def main() -> int:
    missing = [p for p in REQUIRED if not (ROOT / p).exists()]
    leftover = [p for p in FORBIDDEN if (ROOT / p).exists()]
    if missing or leftover:
        if missing:
            print("Нет обязательных файлов:")
            print("\n".join(f"  {p}" for p in missing))
        if leftover:
            print("На витрине осталась кухня:")
            print("\n".join(f"  {p}" for p in leftover))
        return 1
    print(f"OK: {len(REQUIRED)} файлов на месте, кухня не вернулась.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
